import java.io.BufferedInputStream;
import java.io.IOException;

public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value * sign;
        }
    }

    public static void main(String[] args) throws IOException {
        FastScanner fs = new FastScanner();

        int a = fs.nextInt();
        int b = fs.nextInt();

        int[] sequence = new int[a];
        for (int i = 0; i < a; i++) {
            sequence[i] = fs.nextInt();
        }

        int matched = 0;
        for (int i = 0; i < b; i++) {
            int value = fs.nextInt();
            while (matched < a && sequence[matched] != value) {
                matched++;
            }
            if (matched < a) {
                matched++;
            }
        }

        System.out.println(matched == b ? "S" : "N");
    }
}
